}

.hero-content {
  position: relative;
  z-index: 10;
  max-width: 800px;
}

.hero-title {
  font-size: 3.5rem;
  color: var(--color-white);
  margin-bottom: 1.5rem;
}

.hero-subtitle {
  font-size: 1.25rem;
  margin-bottom: 2rem;
  color: var(--color-neutral-gray);
  font-weight: 300;
}

.hero-small {
  height: 50vh;
  min-height: 400px;
}

/* Featured Insights Strip */
.insights-strip {
  background-color: var(--color-teal);
  color: var(--color-white);
  padding: 2rem 0;
}

.insights-strip .container {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}

.insight-strip-item {
  display: flex;
  flex-direction: column;
}

.insight-strip-tag {
  font-size: 0.75rem;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: 0.5rem;
  font-weight: 600;
}

.insight-strip-title {
  font-family: var(--font-sans);
  font-size: 1rem;
  font-weight: 500;
  color: var(--color-white);
}

/* Announcement Banner */
.announcement {
  background-color: var(--color-secondary);
  color: var(--color-white);
  text-align: center;
  padding: 1rem 0;
}

.announcement a {
  color: var(--color-accent);
  font-weight: 600;
  margin-left: 1rem;
}

/* About Statement */
.about-statement {
  text-align: center;
  max-width: 900px;
  margin: 0 auto;
}

.about-statement h2 {
  font-size: 2.5rem;
  margin-bottom: 1.5rem;
}

.about-statement p {
  font-size: 1.25rem;
  color: var(--color-text-light);
  margin-bottom: 2rem;
}

/* What We Do (Tabs) */
.what-we-do-container {
  display: flex;
  gap: 4rem;
  align-items: flex-start;
}

.tabs-list {
  flex: 1;
  display: flex;
  flex-direction: column;
  border-left: 2px solid var(--color-neutral-gray);
}

.tab-btn {
  background: none;
  border: none;
  text-align: left;
  padding: 1.5rem 2rem;
  font-size: 1.5rem;
  font-family: var(--font-serif);
  color: var(--color-text-light);
  cursor: pointer;
  transition: var(--transition);
  position: relative;
  left: -2px;
  border-left: 2px solid transparent;
}

.tab-btn:hover {
  color: var(--color-primary);
}

.tab-btn.active {
  color: var(--color-primary);
  border-left-color: var(--color-accent);
  font-weight: 700;
}

.tabs-content-wrapper {
  flex: 2;
  background-color: var(--color-white);
  padding: 3rem;
  box-shadow: var(--shadow-md);
  border-radius: 4px;
}

.tab-content {
  display: none;
  animation: fadeIn 0.5s;
}

.tab-content.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

.tab-content p {
  font-size: 1.125rem;
  margin-bottom: 2rem;
  color: var(--color-text-light);
}

/* Newsletter */
.newsletter {
  background-color: var(--color-primary);
  color: var(--color-white);
  text-align: center;
  padding: 5rem 0;
  background-image: linear-gradient(rgba(10, 22, 40, 0.9), rgba(10, 22, 40, 0.9)), url('https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&q=80&w=2000');
  background-size: cover;
  background-position: center;
}

.newsletter h2 {
  color: var(--color-white);
  font-size: 2.5rem;
}

.newsletter p {
  font-size: 1.125rem;
  margin-bottom: 2rem;
  color: var(--color-neutral-gray);
}

.newsletter-form {
  display: flex;
  max-width: 500px;
  margin: 0 auto;
}

.newsletter-form input {
  flex: 1;
  padding: 1rem;
  border: none;
  border-radius: 2px 0 0 2px;
  font-family: var(--font-sans);
  outline: none;
}

.newsletter-form button {
  border-radius: 0 2px 2px 0;
  border: none;
}

/* Cards Grid (Insights & Commitments) */
.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}

.grid-4 {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
}

.grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 2rem;
}

.card {
  background: var(--color-white);
  border-radius: 4px;
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: var(--transition);
  height: 100%;
  display: flex;
  flex-direction: column;
}

.card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-5px);
}

.card-img {
  height: 200px;
  background-color: var(--color-neutral-gray);
  object-fit: cover;
  width: 100%;
}

.card-content {
  padding: 1.5rem;
  flex: 1;
  display: flex;
  flex-direction: column;
}

.card-tag {
  font-size: 0.75rem;
  color: var(--color-accent);
  text-transform: uppercase;
  font-weight: 600;
  margin-bottom: 0.5rem;
}

.card-title {
  font-size: 1.25rem;
  margin-bottom: 0.5rem;
}

.card-date {
  font-size: 0.875rem;
  color: var(--color-text-light);
  margin-bottom: 1rem;
}

.card-desc {
  color: var(--color-text-light);
  margin-bottom: 1.5rem;
  flex: 1;
}

.card-link {
  font-weight: 600;
  color: var(--color-primary);
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  margin-top: auto;
}

.card-link:hover {
  color: var(--color-accent);
}

/* Service Categories Grid */
.service-card {
  border: 1px solid var(--color-neutral-gray);
  padding: 2.5rem;
  background: var(--color-white);
  transition: var(--transition);
  border-radius: 4px;
}

.service-card:hover {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-sm);
}

.service-card h3 {
  font-size: 1.5rem;
  margin-bottom: 1rem;
}

.service-card p {
  color: var(--color-text-light);
  margin-bottom: 1.5rem;
}

/* Capabilities Grid */
.capabilities-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}

.capability-item {
  border-top: 2px solid var(--color-primary);
  padding-top: 1.5rem;
}

.capability-item h4 {
  font-size: 1.25rem;
  margin-bottom: 1rem;
  font-family: var(--font-sans);
}

.capability-item p {
  color: var(--color-text-light);
}

/* Featured Partners Carousel */
.carousel-container {
  position: relative;
  overflow: hidden;
  padding: 2rem 0;
}

.carousel-track {
  display: flex;
  transition: transform 0.5s ease;
  gap: 2rem;
}

.carousel-slide {
  min-width: calc(33.333% - 1.33rem);
  flex: 0 0 auto;
}

.carousel-controls {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-top: 2rem;
}

.carousel-btn {
  background: var(--color-white);
  border: 1px solid var(--color-primary);
  color: var(--color-primary);
  width: 40px;
  height: 40px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: var(--transition);
}

.carousel-btn:hover {
  background: var(--color-primary);
  color: var(--color-white);
}

/* Footer */
.footer {
  background-color: var(--color-primary);
  color: var(--color-white);
  padding: 4rem 0 2rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 4rem;
  margin-bottom: 4rem;
}

.footer-about p {
  color: var(--color-neutral-gray);
  margin-top: 1rem;
}

.footer-links h4 {
  font-family: var(--font-sans);
  color: var(--color-white);
  margin-bottom: 1.5rem;
}

.footer-links ul {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.footer-links a {
  color: var(--color-neutral-gray);
}

.footer-links a:hover {
  color: var(--color-accent);
}

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 2rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
  font-size: 0.875rem;
  color: var(--color-neutral-gray);
}

.footer-bottom-links {
  display: flex;
  gap: 1.5rem;
  flex-wrap: wrap;
}

/* Responsive */
@media (max-width: 1024px) {
  .nav-desktop { display: none; }
  .mobile-menu-btn { display: block; }

  .what-we-do-container {
    flex-direction: column;
    gap: 2rem;
  }

  .tabs-list {
    flex-direction: row;
    border-left: none;
    border-bottom: 2px solid var(--color-neutral-gray);
    width: 100%;
    overflow-x: auto;
  }

  .tab-btn {
    border-left: none;
    border-bottom: 2px solid transparent;
    left: 0;
    bottom: -2px;
    padding: 1rem;
    white-space: nowrap;
  }

  .tab-btn.active {
    border-left-color: transparent;
    border-bottom-color: var(--color-accent);
  }

  .grid-4, .grid-3 {
    grid-template-columns: repeat(2, 1fr);
  }

  .capabilities-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .carousel-slide {
    min-width: calc(50% - 1rem);
  }
}

@media (max-width: 768px) {
  .hero-title { font-size: 2.5rem; }
  .insights-strip .container { grid-template-columns: 1fr; }
  .grid-4, .grid-3, .grid-2 { grid-template-columns: 1fr; }
  .capabilities-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; gap: 2rem; }
  .carousel-slide { min-width: 100%; }
}

document.addEventListener('DOMContentLoaded', () => {
  // Mobile Nav Toggle
  const mobileMenuBtn = document.getElementById('mobile-menu-btn');
  const mobileNav = document.getElementById('mobile-nav');

  if (mobileMenuBtn && mobileNav) {
    mobileMenuBtn.addEventListener('click', () => {
      mobileNav.classList.toggle('active');
      const icon = mobileMenuBtn.querySelector('i');
      if (icon) {
        if (mobileNav.classList.contains('active')) {
          icon.className = 'ri-close-line';
        } else {
          icon.className = 'ri-menu-3-line';
        }
      }
    });
  }

  // Mobile Accordion
  const accordionHeaders = document.querySelectorAll('.accordion-header');
  accordionHeaders.forEach(header => {
    header.addEventListener('click', () => {
      const content = header.nextElementSibling;
      const icon = header.querySelector('i');

      content.classList.toggle('active');

      if (icon) {
        if (content.classList.contains('active')) {
          icon.className = 'ri-subtract-line';
        } else {
          icon.className = 'ri-add-line';
        }
      }
    });
  });

  // What We Do Tabs
  const tabBtns = document.querySelectorAll('.tab-btn');
  const tabContents = document.querySelectorAll('.tab-content');

  if (tabBtns.length > 0 && tabContents.length > 0) {
    tabBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        // Remove active class from all
        tabBtns.forEach(b => b.classList.remove('active'));
        tabContents.forEach(c => c.classList.remove('active'));

        // Add active class to clicked
        btn.classList.add('active');
        const targetId = btn.getAttribute('data-target');
        const targetContent = document.getElementById(targetId);
        if (targetContent) {
          targetContent.classList.add('active');
        }
      });
    });
  }

  // Carousel
  const track = document.querySelector('.carousel-track');
  const prevBtn = document.getElementById('carousel-prev');
  const nextBtn = document.getElementById('carousel-next');

  if (track && prevBtn && nextBtn) {
    let currentIndex = 0;
    const slides = Array.from(track.children);

    function updateCarousel() {
      const slideWidth = slides[0].getBoundingClientRect().width;
      const gap = parseFloat(window.getComputedStyle(track).gap) || 32; // 2rem
      track.style.transform = `translateX(-${currentIndex * (slideWidth + gap)}px)`;
    }

    nextBtn.addEventListener('click', () => {
      if (currentIndex < slides.length - 1) {
        currentIndex++;
        updateCarousel();
      }
    });

    prevBtn.addEventListener('click', () => {
      if (currentIndex > 0) {
        currentIndex--;
        updateCarousel();
      }
    });

    window.addEventListener('resize', updateCarousel);
  }
});
